/// mode, and target, `new` or a story's id, then, after a blank line, its
/// prompt. None for a block with neither title nor prompt.
pub fn parse_story_block(body: &str) -> Option<Proposal> {
    let mut proposal = Proposal {
        id: proposal_id(),
        title: String::new(),
        prompt: String::new(),
        mode: "chain".into(),
        target: None,
        note: None,
        about: None,
        spec: Vec::new(),
        dropped: Vec::new(),
    };
    let mut lines = body.lines();
    let mut prompt: Vec<&str> = Vec::new();
    let mut in_spec = false;
    for line in lines.by_ref() {
        if line.trim().is_empty() {
            break;
        }
        // The spec list: its entries, one per line, each begun with a dash.
        if in_spec && line.trim_start().starts_with(['-', '*']) {
            proposal.spec.extend(Citation::parse(line));
            continue;
        }
        in_spec = false;
        let Some((key, value)) = line.split_once(':') else {
            prompt.push(line);
            break;
        };
        let value = value.trim();
        match key.trim().to_ascii_lowercase().as_str() {
            "title" => proposal.title = value.to_string(),
            "mode" => {
                if let Some(mode) = mode_of_slug(value) {
                    proposal.mode = mode_slug(mode).into();
                }
            }
            "target" => {
                proposal.target = (!value.is_empty() && !value.eq_ignore_ascii_case("new"))
                    .then(|| value.to_string());
            }
            "spec" => {
                in_spec = true;
                proposal.spec.extend(Citation::parse(value));
            }
            "prompt" => {
                if !value.is_empty() {
                    prompt.push(value);
                }
                break;
            }
            _ => {
                prompt.push(line);
                break;
            }
        }
    }
