    /// A draft of one story: its rewrite, and a step for it.
    fn full_story(
        _: &Path,
        request: &str,
        _: &Cancel,
        _: &dyn Fn(String),
    ) -> anyhow::Result<String> {
        use crate::baked_prompts::planning;
        assert!(request.contains(planning::STORY), "it isn't asked for a full story");
        let about = request
            .lines()
            .find_map(|line| line.strip_prefix(planning::ABOUT)?.strip_prefix(": "))
            .expect("it isn't told the story")
            .trim()
            .to_string();
        let title = request
            .lines()
            .find_map(|line| line.strip_prefix("Title: "))
            .expect("it isn't told the title");
        assert!(request.contains("Mode: chain"), "it isn't told the mode");
        Ok(format!(
            "```suspense-story\\ntitle: {title}, in full\\nmode: code\\ntarget: rewrite\\nspec:\\n- No match — {title}\\n\\nAll of {title}.\\n```\\n\\n```suspense-story\\ntitle: Then\\nmode: code\\ntarget: {about}\\nspec:\\n- No match — after\\n\\nThen {title}.\\n```\\n"
        ))
    }

    /// A block can rewrite the story it is about.
    #[test]
    fn a_block_can_rewrite_its_story() {
        let proposal =
            parse_story_block("title: Whole\\nmode: code\\ntarget: rewrite\\nspec:\\n- No match — it\\n\\nAll of it.")
                .unwrap();
        assert!(proposal.rewrite);
        assert_eq!(proposal.target, None);
    }

    /// Draft with agent drafts each story in a run of its own, all at
    /// once, never taking over the side panel; what each proposes waits for
    /// its story, saved a file per story, and accepting its rewrite rewrites
